module pulse_detect(
    input clk,
    input rst_n,
    input data_in,
    output reg data_out
);
    // Define states
    parameter s0 = 2'b00; // Initial state, waiting for pulse 0
    parameter s1 = 2'b01; // State, waiting for pulse 1
    parameter s2 = 2'b10; // State, waiting for pulse 0
    parameter s3 = 2'b11; // State, waiting for pulse 1
    // State register
    reg [1:0] pulse_level1, pulse_level2;
    // Sequencial logic
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            pulse_level1 <= s0;
        end else begin
            pulse_level1 <= pulse_level2;
        end
    end
    // Combinational logic for pulse_level2
    always @(*) begin
        if (pulse_level1 == s0) begin
            if (data_in == 0) begin
                pulse_level2 = s1;
            end else begin
                pulse_level2 = s0;
            end
        end else if (pulse_level1 == s1) begin
            if (data_in == 1) begin
                pulse_level2 = s2;
            end else begin
                pulse_level2 = s1;
            end
        end else if (pulse_level1 == s2) begin
            if (data_in == 0) begin
                pulse_level2 = s3;
            end else begin
                pulse_level2 = s0;
            end
        end else if (pulse_level1 == s3) begin
            if (data_in == 1) begin
                pulse_level2 = s2;
            end else begin
                pulse_level2 = s1;
            end
        end
    end
    // Output logic
    always @(*) begin
        if (~rst_n) begin
            data_out = 0;
        end else begin
            if (pulse_level2 == s2 && data_in == 0) begin
                data_out = 1;
            end else begin
                data_out = 0;
            end
        end
    end
endmodule
